//! What the caption fixture tests share: the fixture, and its caption
//! elementary stream and PES packets as the demuxer of `mpeg2-systems`
//! reports them

use mpeg2_systems::pes::StreamId;
use mpeg2_systems::stream_type::StreamType;
use mpeg2_systems::ts::demux::{Demuxer, DemuxerConfig, Event};

/// The ARIB caption Transport Stream, generated by
/// `cargo xtask fixtures --arib`
pub(crate) const CAPTION: &[u8] = include_bytes!("../fixtures/caption.ts");

/// An elementary stream the PMT names: its PID, its `stream_type` and the
/// bytes of its descriptors
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct ElementaryStream {
    pub(crate) pid: u16,
    pub(crate) stream_type: StreamType,
    pub(crate) es_info: Vec<u8>,
}

/// A PES packet of a private data stream: its PTS, its `stream_id` and its
/// payload
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct PrivatePesPacket {
    pub(crate) pts: Option<u64>,
    pub(crate) stream_id: StreamId,
    pub(crate) payload: Vec<u8>,
}

/// Reads the fixture Transport Packet by Transport Packet, subscribing to
/// each PES private data stream as the PMT names it, and returns the
/// elementary streams and the PES packets of the private data streams
pub(crate) fn read() -> (Vec<ElementaryStream>, Vec<PrivatePesPacket>) {
    let mut demuxer = Demuxer::new(DemuxerConfig::default());
    let mut streams = Vec::new();
    let mut packets = Vec::new();
    let mut take = |demuxer: &mut Demuxer| {
        let mut subscribe = Vec::new();
        while let Some(event) = demuxer.poll_event() {
            if let Event::TsProgramMapSection { section, .. } = &event {
                for stream in section.elementary_streams.iter() {
                    let stream = stream.unwrap();
                    if stream.stream_type == StreamType::ISO_IEC_13818_1_PES_PRIVATE_DATA {
                        subscribe.push(stream.elementary_pid);
                    }
                    streams.push(ElementaryStream {
                        pid: stream.elementary_pid.get(),
                        stream_type: stream.stream_type,
                        es_info: stream.es_info.as_bytes().to_vec(),
                    });
                }
            }
            if let Event::PesPacket { packet, .. } = &event {
                packets.push(PrivatePesPacket {
                    pts: packet
                        .optional_header
                        .as_ref()
                        .and_then(|header| header.pts)
                        .map(|pts| pts.get()),
                    stream_id: packet.stream_id,
                    payload: packet.payload.to_vec(),
                });
            }
        }
        subscribe
    };
    // Why not hand the stream over whole: the caption PID is subscribed to
    // when the PMT names it, as a caller finds it, and the PES packets after
    // the PMT come in later Transport Packets.
    for packet in CAPTION.chunks(188) {
        demuxer.handle_input(packet);
        for pid in take(&mut demuxer) {
            demuxer.subscribe_pes(pid);
        }
    }
    demuxer.finish();
    take(&mut demuxer);

    (streams, packets)
}
